class gsl_combination:
    def __init__(self, n, k):
        self.n = n
        self.k = k
        self.comb = libgslcblas.gsl_combination_alloc(n, k)
        if not self.comb:
            raise Exception('allocation failed')

    def init_first(self):
        libgsl.gsl_combination_init_first(self.comb)

    def get_data(self):
        data = [0] * self.k
        for i in range(self.k):
            data[i] = libgslcblas.gsl_combination_get(self.comb, i)
        return data

    def free(self):
        libgslcblas.gsl_combination_free(self.comb)

