def compute_moving_median(data: List[float], window_size: int) -> List[float]:
    medians = []
    for i in range(len(data) - window_size + 1):
        start_idx = i
        end_idx = i + window_size
        window_data = np.array(data[start_idx:end_idx])
        data_ptr = ctypes.c_double * len(window_data)
        data_ptr_arr = data_ptr(*window_data)

        gsl_sort_alloc(len(window_data))
        gsl_cblas_gslsort(data_ptr_arr, len(window_data))
        gsl_cblas_dsort(data_ptr_arr, len(window_data))
        median_idx = (len(window_data) - 1) // 2 if len(window_data) % 2 else len(window_data) // 2
        medians.append(window_data[median_idx])

    return medians\n

