class gsl_permutation:
    def __init__(self):
        self.data = ctypes.c_int * 1
    def free(self):
        del self.data

    class gsl_vector:
        def __init__(self, n):
            self.data = c_double * n
        def free(self):
            del self.data

def permute_vector(perm, vec):
    if len(perm) != len(vec):
        raise ValueError("Permutation and vector lengths must match")

    p = gsl_permutation()
    v = vec[:]
    for i in range(len(p)):
        p.data[0] = perm[i]
    c_perm = p.data
    c_vec = (c_double * len(v))(*v)
    p.free()

    res = (c_double * len(v))()
    gsl.gsl_permute_vector(c_perm, c_vec, res)

    return list(res)
