class QuadraticParams(ctypes.Structure):
    _fields_ = [('a', ctypes.c_double), ('b', ctypes.c_double), ('c', ctypes.c_double)]

def quadratic_fdf(x, params, y=None, dy=None):
    if y is None and dy is not None:
        raise ValueError('y must be provided when calculating derivative')
    elif y is not None and dy is None:
        return y, 0.0
    else:
        y = (params.a * x**2) + (params.b * x) + params.c
        if dy is not None:
            dy = (2*params.a*x) + params.b
        return y, dy

def compute_quadratic_and_derivative(a, b, c, x):
    params = QuadraticParams(a=a, b=b, c=c)
    result, derivative = quadratic_fdf(x, params)
    return result, derivative

