class GSLSpMatrix:
    def __init__(self, num_rows, num_cols, data):
        self.num_rows = num_rows
        self.num_cols = num_cols
        self.data = data

    def to_csr(self):
        row_idx = np.zeros(self.num_rows + 1, dtype=np.int32)
        col_ptr = np.zeros(self.num_cols + 1, dtype=np.int32)
        for i in range(len(self.data)):
            row_idx[i // self.num_cols] += 1
            col_ptr[i % self.num_cols] = i // self.num_cols
        return csr_matrix((self.data, (row_idx[:-1], col_ptr[:-1])), shape=(self.num_rows, self.num_cols)).tocsr()

    def perform_matrix_operation(self, spmatrix):
        libgslcblas.gsl_spmatrix_view_create.restype = ctypes.POINTER(ctypes.c_void_p)
        view = libgslcblas.gsl_spmatrix_view_create(self.to_csr(), self.num_rows, self.num_cols, 0)
        if not view:
            raise ValueError("Failed to create GSL sparse matrix view")
        try:
            result = libgslcblas.gsl_spmatrix_multiply(view, spmatrix.to_csr(), None)
        finally:
            libgslcblas.gsl_spmatrix_view_free(view)

    def run(self, spmatrix):
        return self.perform_matrix_operation(spmatrix).toarray()

