gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
gsl_cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)

def create_gsl_vector(data):
    vec = gsl.gsl_vector_alloc(len(data))
    for i in range(len(data)):
        gsl.gsl_vector_set(vec, i, data[i])
    return vec

def extract_gsl_vector(vec, size):
    data = [0] * size
    for i in range(size):
        data[i] = gsl.gsl_vector_get(vec, i)
    return data

def gsl_filter_impulse_python(input_data, t, K):
    if len(input_data) != K:
        raise ValueError("Input vector length must be equal to K")

    input_gsl_vec = create_gsl_vector(input_data)
    output_gsl_vec = gsl.gsl_vector_alloc(K)

    result = gsl_cblas.gsl_filter_impulse_alloc(K, t)
    if not result:
        raise RuntimeError("gsl_filter_impulse_alloc failed")

    try:
        for i in range(K):
            gsl_cblas.gsl_filter_impulse(result, K, input_gsl_vec, output_gsl_vec)
        return extract_gsl_vector(np.array(output_gsl_vec), K), 0
    finally:
        if result:
            gsl_cblas.gsl_filter_impulse_free(result)

def main(input_data, t, K):
    try:
        filtered_data, outliers = gsl_filter_impulse_python(input_data, t, K)
        return json.dumps({"filtered_data": str(filtered_data.tolist()), "outliers": outliers})
    except ValueError as e:
        return json.dumps({"error": str(e)})
    except RuntimeError as e:
        return json.dumps({"error": str(e)})

