class GSLMatrix:
    def __init__(self, size):
        self.size = size
        self.mat = (ctypes.c_double * size**2)()
        self.handle = gsl.matrix_alloc(size, size)

    def set_elements(self, row, col, value):
        if 0 <= row < self.size and 0 <= col < self.size:
            self.mat[row*self.size + col] = value
            self._set_element(self.handle, row, col, value)

    def _set_element(self, handle, row, col, value):
        return gsl.matrix_set(self, handle, row, col, value)

    def get_elements(self):
        result = {}
        for i in range(self.size):
            for j in range(self.size):
                result[(i, j)] = self.mat[i*self.size + j]
        return result

    def __del__(self):
        gsl.matrix_free(self.handle)

def create_and_manipulate_matrix():
    mat = GSLMatrix(2)
    for i in range(2):
        for j in range(2):
            mat.set_elements(i, j, i*2+j+1)
    return mat.get_elements()

