gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

def compute_gaussian_cdf_and_inverse(x):
    x = ctypes.c_double(x).value
    cdf_p = gsl.cdf_ugaussian_P(x)
    cdf_q = gsl.cdf_ugaussian_Q(x)
    inv_cdf_p = gsl.cdf_ugaussian_Pinv(x)
    inv_cdf_q = gsl.cdf_ugaussian_Qinv(x)

    if isnan(cdf_p) or isinf(cdf_p):
        cdf_p = float('nan')
    if isinf(cdf_p):
        cdf_p = 0.0

    if isnan(cdf_q) or isinf(cdf_q):
        cdf_q = float('nan')
    if isinf(cdf_q):
        cdf_q = 0.0

    if isnan(inv_cdf_p) or isinf(inv_cdf_p):
        inv_cdf_p = float('nan')
    if isinf(inv_cdf_p):
        inv_cdf_p = 0.0

    if isnan(inv_cdf_q) or isinf(inv_cdf_q):
        inv_cdf_q = float('nan')
    if isinf(inv_cdf_q):
        inv_cdf_q = 0.0

    return [cdf_p, cdf_q, inv_cdf_p, inv_cdf_q]

