                gsl_matrix.set(j, i-1, self.matrix[i][j])
        L = POINTER(c_double)(c_double*len(self.matrix))
        try:
            int(gsl.linalg_cholesky_decomp(gsl_matrix, byref(L)).contents.value) == 0
            return [[L[i*len(self.matrix[0]) + j] for j in range(len(self.matrix))] for i in range(len(self.matrix))]
