def compute_histogram(data, xmin, xmax):
    import ctypes.util
    ctypes.CDLL('m')

    data = [float(x) for x in data]

    hist = gsl.histogram(0)
    for i in range(len(data)):
        value = data[i]
        if value < xmin or value > xmax:
            continue
        int_value = int((value - xmin) * (hist.n - 1) / (xmax - xmin))
        if int_value < 0:
            int_value = 0
        elif int_value >= hist.n:
            continue
        else:
            hist.x[int_value] = value

    bins = []
    for i in range(hist.n):
        x, count = float(hist.x[i]), hist.y[i]
        if i == 0:
            lower_bound = xmin
        else:
            lower_bound = float(hist.x[i-1])
        upper_bound = float(hist.x[i]) + (float(xmax) - float(xmin)) / (hist.n - 1)
        bins.append((lower_bound, upper_bound, count))

    return json.dumps(bins)

